package ma.seatflow.event;
import ma.seatflow.shared.ApiError.*;import java.security.Principal;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin") public class AdminController {private final JdbcTemplate db;public AdminController(JdbcTemplate d){db=d;}
 @GetMapping("/venues") public List<Map<String,Object>> venues(){return db.queryForList("SELECT h.id,h.name,v.name AS venue,(SELECT count(*) FROM seat WHERE hall_id=h.id) AS seats FROM hall h JOIN venue v ON v.id=h.venue_id");}
 @GetMapping("/seasons") public List<Map<String,Object>> seasons(){return db.queryForList("SELECT * FROM season ORDER BY id");}
 @GetMapping("/report") public List<Map<String,Object>> report(){return db.queryForList("SELECT e.id,e.title,c.name AS sector,count(*) AS capacity,count(*) FILTER (WHERE es.status='SOLD') AS sold,count(*) FILTER (WHERE es.status='PASS') AS protected FROM event_seat es JOIN event e ON e.id=es.event_id JOIN seat s ON s.id=es.seat_id JOIN sector c ON c.id=s.sector_id GROUP BY e.id,e.title,c.name ORDER BY e.id,c.name");}
 public record NewEvent(long hallId,Long seasonId,String title,String description,Instant startsAt,Instant endsAt,int setupMinutes,int teardownMinutes,Instant priorityOpensAt,Instant publicOpensAt){}
 @Transactional @PostMapping("/events") public Map<String,Object> create(Principal p,@RequestBody NewEvent r){if(r.title()==null||r.title().isBlank()||r.title().length()>160||r.description()==null||r.description().length()>4000||r.publicOpensAt()==null)throw new Bad("Titre, description et ouverture au public valides requis");if(r.priorityOpensAt()!=null&&r.priorityOpensAt().isAfter(r.publicOpensAt()))throw new Bad("L’ouverture prioritaire doit précéder l’ouverture publique");if(r.publicOpensAt()!=null&&r.startsAt()!=null&&r.publicOpensAt().isAfter(r.startsAt()))throw new Bad("L’ouverture publique doit précéder l’événement");if(r.startsAt()==null||r.endsAt()==null||!r.endsAt().isAfter(r.startsAt())||r.setupMinutes()<0||r.teardownMinutes()<0)throw new Bad("Horaires invalides");if(r.seasonId()!=null)db.queryForMap("SELECT id FROM season WHERE id=? FOR UPDATE",r.seasonId());db.queryForMap("SELECT id FROM hall WHERE id=? FOR UPDATE",r.hallId());long id=db.queryForObject("INSERT INTO event(hall_id,season_id,title,description,starts_at,ends_at,occupied_start,occupied_end,setup_minutes,teardown_minutes,priority_opens_at,public_opens_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,r.hallId(),r.seasonId(),r.title(),r.description(),java.sql.Timestamp.from(r.startsAt()),java.sql.Timestamp.from(r.endsAt()),java.sql.Timestamp.from(r.startsAt().minusSeconds(r.setupMinutes()*60L)),java.sql.Timestamp.from(r.endsAt().plusSeconds(r.teardownMinutes()*60L)),r.setupMinutes(),r.teardownMinutes(),r.priorityOpensAt()==null?null:java.sql.Timestamp.from(r.priorityOpensAt()),java.sql.Timestamp.from(r.publicOpensAt()));db.update("INSERT INTO tariff(event_id,category,price) SELECT ?,category,CASE category WHEN 'VIP' THEN 350 WHEN 'ACCESSIBLE' THEN 120 ELSE 180 END FROM sector WHERE hall_id=? GROUP BY category",id,r.hallId());db.update("INSERT INTO event_seat(event_id,seat_id,price) SELECT ?,s.id,t.price FROM seat s JOIN sector c ON c.id=s.sector_id JOIN tariff t ON t.event_id=? AND t.category=c.category WHERE s.hall_id=?",id,id,r.hallId());if(r.seasonId()!=null){var passes=db.queryForList("SELECT sp.id,sp.owner_id,sp.seat_id FROM season_pass sp JOIN seat s ON s.id=sp.seat_id WHERE sp.season_id=? AND sp.type='FIXED' AND s.hall_id=? ORDER BY sp.seat_id FOR UPDATE OF sp",r.seasonId(),r.hallId());for(var pass:passes){var rows=db.queryForList("SELECT id,status FROM event_seat WHERE event_id=? AND seat_id=? FOR UPDATE",id,pass.get("seat_id"));if(rows.isEmpty()||!"AVAILABLE".equals(rows.get(0).get("status")))throw new Conflict("Abonnement fixe incompatible avec cet événement");long eventSeat=((Number)rows.get(0).get("id")).longValue();db.update("UPDATE event_seat SET status='PASS',pass_owner=? WHERE id=?",pass.get("owner_id"),eventSeat);db.update("INSERT INTO season_seat_assignment(pass_id,event_id,event_seat_id) VALUES(?,?,?)",pass.get("id"),id,eventSeat);db.update("INSERT INTO ticket(event_seat_id,event_id,owner_id,code,status) VALUES(?,?,?,gen_random_uuid(),'ACTIVE')",eventSeat,id,pass.get("owner_id"));}}db.update("UPDATE hall SET layout_frozen=true WHERE id=?",r.hallId());db.update("INSERT INTO audit_entry(actor_id,action,entity_type,entity_id) VALUES((SELECT id FROM app_user WHERE username=?),'EVENT_CREATE','EVENT',?)",p.getName(),id);return Map.of("id",id);}
}
